def L(slug, title, level, minutes, pri, prereqs, objectives, concepts, res, arch=None):
    return dict(slug=slug, title=title, level=level, minutes=minutes, priority=pri, prereqs=prereqs,
                objectives=objectives, concepts=concepts, resources=res, archNodes=arch or [])

