# ----------------------------------------------------------------------------- existing data (for the index)
cur = open(f"{ROOT}/data/curriculum.ts", encoding="utf-8").read()  # the pack's merged copy (module lists reflect the url-shortener move)
cur_repo = open(f"{REPO}/data/curriculum.ts", encoding="utf-8").read()  # original levels for the before/after comparison
EXISTING_MODULES = []
for m in re.finditer(r'\{ id: "([a-z]+)", number: (\d+), title: "([^"]+)", tagline: "([^"]+)", stage: "([^"]+)",\s*description: "([^"]+)",\s*lessons: \[([^\]]+)\] \}', cur):
    if m.group(1) in {nm["id"] for nm in NEW_MODULES}: continue  # new modules live in NEW_MODULES; the pack's curriculum.ts grows as bundles merge
    EXISTING_MODULES.append(dict(id=m.group(1), number=int(m.group(2)), title=m.group(3), tagline=m.group(4), stage=m.group(5), description=m.group(6), lessons=re.findall(r'"([a-z0-9-]+)"', m.group(7))))
EXISTING_META = {}
for m in re.finditer(r'slug: "([a-z0-9-]+)", title: "([^"]+)", moduleId: "([a-z]+)", level: "([a-z]+)", minutes: (\d+)', cur_repo):
    EXISTING_META[m.group(1)] = dict(title=m.group(2), module=m.group(3), level=m.group(4), minutes=int(m.group(5)))
assert len(EXISTING_META) == 42 and set(EXISTING_META) == set(EXISTING)

# ----------------------------------------------------------------------------- checks
all_new = [l for m in NEW_MODULES for l in m["lessons"] if not l.get("existing")]
slugs = set(EXISTING_META) | {l["slug"] for l in all_new}
assert len(slugs) == 42 + len(all_new), "duplicate slug"
for l in all_new:
    for p in l["prereqs"]:
        assert p in slugs, f"{l['slug']}: unknown prereq {p}"
    assert re.fullmatch(r"[a-z0-9-]+", l["slug"]), l["slug"]
    assert l["level"] in ("basic","intermediate","advanced")
    assert l["priority"] in ("P1","P2","P3")
# prerequisite must come earlier in the overall order
order = [s for m in EXISTING_MODULES for s in m["lessons"]] + [l["slug"] for m in NEW_MODULES for l in m["lessons"]]
pos = {s: i for i, s in enumerate(order)}
for l in all_new:
    for p in l["prereqs"]:
        assert pos[p] < pos[l["slug"]], f"{l['slug']} prereq {p} comes later"

plan = dict(generated="2026-11-22", repo_head="e508232", existing_modules=EXISTING_MODULES, existing_lessons={s: {**EXISTING_META[s], **EXISTING[s]} for s in EXISTING_META}, new_modules=NEW_MODULES)
json.dump(plan, open(os.path.join(ROOT, "plan", "curriculum-plan.json"), "w", encoding="utf-8"), indent=1, ensure_ascii=False)

# ----------------------------------------------------------------------------- stats
levels = {"basic":0,"intermediate":0,"advanced":0}
for s, m in EXISTING_META.items():
    lv = EXISTING[s]["reclassify"] or m["level"]; levels[lv] += 1
for l in all_new: levels[l["level"]] += 1
pri = {"P1":0,"P2":0,"P3":0}
for l in all_new: pri[l["priority"]] += 1
mins_new = sum(l["minutes"] for l in all_new)
print("new lessons:", len(all_new), "| new modules:", len(NEW_MODULES), "| total lessons:", 42+len(all_new))
print("levels after plan:", levels, "| priorities:", pri, "| new minutes:", mins_new)
for m in NEW_MODULES:
    lv = {}
    for l in m["lessons"]:
        if l.get("existing"): continue
        lv[l["level"]] = lv.get(l["level"],0)+1
    print(f"  {m['number']:>2} {m['id']:<15} {len(m['lessons']):>2} lessons {sum(l['minutes'] for l in m['lessons'] if not l.get('existing')):>3} min  {lv}")
